/**
 * Sending OMEMO: the send policy, the fan-out and the ratchet step (ADR 0006 §7).
 *
 * Every key here is generated by `@curlew/omemo` and every address is synthetic. The peers are
 * real devices of our own code rather than recorded blobs, so a round trip tests what stage 2
 * actually accepts: the message is encrypted here and opened by `receiveOmemo` there.
 *
 * The one property most of these cases exist for: a peer who has OMEMO devices is NEVER sent
 * plaintext. A failed fetch, a bundle that is gone, a key that changed — each of them ends in a
 * refusal or in a skipped device, and nowhere in this file does a send fall back to the clear.
 */

import { describe, expect, it } from '@gjsify/unit';
import xml from '@xmpp/xml';

import {
  LEGACY_PROFILE,
  MemoryOmemoStorage,
  addressKey,
  generateKeyPair,
  selectBundleKeys,
  toBase64,
  type DeviceAddress,
  type DeviceId,
  type OmemoStorage,
  type SessionRecord,
} from '@curlew/omemo';
import { SecretStore } from '@curlew/store';
import {
  announceDevice,
  bundleNode,
  encryptOmemo,
  encryptedChatMessage,
  ensureBundle,
  ensureOwnDevice,
  isOmemoSendRefusedError,
  NS,
  omemoEncryptFor,
  omemoHeartbeat,
  parseEncryptedElement,
  planOmemoSend,
  receiveOmemo,
  recipientTrust,
  SecretStoreOmemoStorage,
  XmppQueryError,
  type IdentityChange,
  type OmemoSendPlan,
  type OwnDevice,
  type PepPort,
  type XmlElement,
} from '@curlew/xmpp';

import { LATER, START, fakeNetwork, join, joinWith, type Participant } from './fake-pep.ts';

const ALICE = 'alice@example.org';
const BOB = 'bob@example.org';

/**
 * A `MemoryOmemoStorage` that also keeps the parked key changes, which the plain one drops.
 *
 * The journal half of `TrustStorage` is optional, so the send path runs either way; a case that
 * wants to see WHAT was parked needs somewhere for it to land.
 */
class ParkingStorage extends MemoryOmemoStorage {
  readonly parked = new Map<string, IdentityChange>();

  async saveIdentityChange(address: DeviceAddress, change: IdentityChange): Promise<void> {
    this.parked.set(addressKey(address), change);
  }

  async loadIdentityChange(address: DeviceAddress): Promise<IdentityChange | undefined> {
    return this.parked.get(addressKey(address));
  }
}

/** Encrypt from `from` to `to`'s JID, asking the server rather than the cache. */
async function sendTo(from: Participant, to: string, text: string | null) {
  return omemoEncryptFor(from.pep, from.storage, from.device, from.jid, to, text, { now: () => LATER });
}

/** Run and return the refusal, or fail: a send that went through is the bug these cases watch. */
async function refusal(run: () => Promise<unknown>): Promise<{ reason: string; skipped: number }> {
  try {
    await run();
  } catch (err) {
    if (!isOmemoSendRefusedError(err)) throw err;
    return { reason: err.reason, skipped: err.skipped.length };
  }
  throw new Error('expected the send to be refused');
}

/** A bundle to start a session from, without a network: the keys of a freshly made device. */
async function standaloneBundle(storage: OmemoStorage = new MemoryOmemoStorage()) {
  const device = await ensureOwnDevice(storage);
  const state = await ensureBundle(storage, device, { now: () => START });
  return { device, keys: selectBundleKeys(state.bundle) };
}

/** A `SecretStoreOmemoStorage` whose nth `saveSession` throws, to test the transaction. */
class FlakyStorage extends SecretStoreOmemoStorage {
  failAfter = Number.POSITIVE_INFINITY;
  #saves = 0;

  override async saveSession(address: DeviceAddress, record: SessionRecord): Promise<void> {
    if (++this.#saves > this.failAfter) throw new Error('the account file is gone');
    await super.saveSession(address, record);
  }
}

export default async function omemoSend(): Promise<void> {
  await describe('what a send is planned for', async () => {
    await it('addresses the peer and our own other devices, never this one', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const alicePhone = await join(net, ALICE);
      const bob = await join(net, BOB);

      const plan = await planOmemoSend(alice.pep, alice.storage, alice.device, ALICE, BOB, {
        now: () => LATER,
      });
      const ids = plan?.recipients.map((r) => `${r.address.jid}:${String(r.address.deviceId)}`).sort();
      expect(ids?.join(' ')).toBe(
        [`${ALICE}:${String(alicePhone.device.deviceId)}`, `${BOB}:${String(bob.device.deviceId)}`]
          .sort()
          .join(' '),
      );
      expect(plan?.staleDeviceList).toBe(false);
      expect(plan?.skipped.length).toBe(0);
    });

    await it('answers null when the peer publishes no OMEMO devices at all', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      // The one case where plaintext is right, and saying so is the whole answer.
      expect(await sendTo(alice, 'stranger@example.org', 'hi')).toBe(null);
    });

    await it('refuses when the device list cannot be read and nothing is cached', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      await join(net, BOB);
      net.fail(BOB);
      expect((await refusal(() => sendTo(alice, BOB, 'hi'))).reason).toBe('device-list-failed');
    });

    await it('sends to a stale cached list rather than sending in the clear', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const bob = await join(net, BOB);
      await sendTo(alice, BOB, 'first');

      net.fail(BOB);
      const muchLater = new Date(LATER.getTime() + 2 * 60 * 60 * 1000);
      const plan = await planOmemoSend(alice.pep, alice.storage, alice.device, ALICE, BOB, {
        now: () => muchLater,
      });
      expect(plan?.staleDeviceList).toBe(true);
      expect(plan?.recipients.length).toBe(1);
      expect(plan?.recipients[0].address.deviceId).toBe(bob.device.deviceId);
    });

    await it('survives our own device list failing: the peer is what the rule protects', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      await join(net, ALICE);
      const bob = await join(net, BOB);
      net.fail(ALICE);

      const plan = await planOmemoSend(alice.pep, alice.storage, alice.device, ALICE, BOB, {
        now: () => LATER,
      });
      expect(plan?.recipients.length).toBe(1);
      expect(plan?.recipients[0].address.jid).toBe(BOB);
      expect(plan?.recipients[0].address.deviceId).toBe(bob.device.deviceId);
    });

    await it('skips one unreachable device of the peer and sends to the other', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const laptop = await join(net, BOB);
      const phone = await join(net, BOB);
      net.fail(BOB, bundleNode(phone.device.deviceId));

      const plan = await planOmemoSend(alice.pep, alice.storage, alice.device, ALICE, BOB, {
        now: () => LATER,
      });
      expect(plan?.recipients.length).toBe(1);
      expect(plan?.recipients[0].address.deviceId).toBe(laptop.device.deviceId);
      expect(plan?.skipped.map((s) => s.reason).join()).toBe('bundle-failed');
    });

    await it('refuses when no device of the peer has a usable bundle', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const bob = await join(net, BOB);
      net.fail(BOB, bundleNode(bob.device.deviceId));
      const refused = await refusal(() => sendTo(alice, BOB, 'hi'));
      expect(refused.reason).toBe('no-usable-bundle');
      expect(refused.skipped).toBe(1);
    });

    await it('skips a distrusted device and refuses when every one of them is', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const bob = await join(net, BOB);
      await alice.storage.saveIdentity(
        { jid: BOB, deviceId: bob.device.deviceId },
        {
          publicKey: toBase64(bob.device.identityKey.publicKey),
          trust: 'distrusted',
          firstSeen: START.toISOString(),
        },
      );
      const refused = await refusal(() => sendTo(alice, BOB, 'hi'));
      expect(refused.reason).toBe('no-trusted-device');
      expect(refused.skipped).toBe(1);
    });

    await it('parks a published key that replaced the one we hold, and refuses', async () => {
      const net = fakeNetwork();
      const storage = new ParkingStorage();
      const alice = await joinWith(net, ALICE, storage);
      const bob = await join(net, BOB);
      // A key under a device id we already know is never adopted off a bundle: that decision is
      // the person's, so the key waits in the journal until they compare its fingerprint.
      const held = toBase64(generateKeyPair().publicKey);
      await storage.saveIdentity(
        { jid: BOB, deviceId: bob.device.deviceId },
        { publicKey: held, trust: 'blind', firstSeen: START.toISOString() },
      );

      const refused = await refusal(() => sendTo(alice, BOB, 'hi'));
      expect(refused.reason).toBe('identity-changed');
      expect(refused.skipped).toBe(1);

      // The published key is parked, the held one still stands, and the change is dated when it
      // was seen rather than when it was published.
      const change = storage.parked.get(addressKey({ jid: BOB, deviceId: bob.device.deviceId }));
      expect(change?.publicKey).toBe(toBase64(bob.device.identityKey.publicKey));
      expect(change?.seenAt).toBe(LATER.toISOString());
      const stored = await storage.loadIdentity({ jid: BOB, deviceId: bob.device.deviceId });
      expect(stored?.publicKey).toBe(held);
    });

    await it('refuses a peer without devices when encryption is required there', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);

      // Bob never announced, so there is nothing to encrypt to. Without the setting that is a
      // plaintext send (null); with it, the message does not go at all.
      expect(await sendTo(alice, BOB, 'hi')).toBe(null);
      const refused = await refusal(() =>
        omemoEncryptFor(alice.pep, alice.storage, alice.device, ALICE, BOB, 'hi', {
          now: () => LATER,
          requireEncryption: true,
        }),
      );
      expect(refused.reason).toBe('encryption-required');
      expect(refused.skipped).toBe(0);
    });

    await it('plans nothing for a peer without devices unless encryption is required', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);

      expect(
        await planOmemoSend(alice.pep, alice.storage, alice.device, ALICE, BOB, { now: () => LATER }),
      ).toBe(null);
      expect(
        (
          await refusal(() =>
            planOmemoSend(alice.pep, alice.storage, alice.device, ALICE, BOB, {
              now: () => LATER,
              requireEncryption: true,
            }),
          )
        ).reason,
      ).toBe('encryption-required');
    });
  });

  await describe('encrypting for the planned devices', async () => {
    await it('is opened by the peer, with a key exchange only on the first message', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const bob = await join(net, BOB);

      const first = await sendTo(alice, BOB, 'the roof is leaking');
      expect(first?.keys.length).toBe(1);
      expect(first?.keys[0].keyExchange).toBe(true);
      const opened = await receiveOmemo(bob.storage, bob.device, ALICE, first!, { now: () => LATER });
      expect(opened.kind).toBe('decrypted');
      expect(opened.kind === 'decrypted' ? opened.text : null).toBe('the roof is leaking');
      expect(opened.kind === 'decrypted' ? opened.senderDeviceId : 0).toBe(alice.device.deviceId);

      // Bob answers, which is what finishes the key exchange on Alice's side.
      const reply = await sendTo(bob, ALICE, 'since when?');
      expect(reply?.keys[0].keyExchange).toBe(false);
      const back = await receiveOmemo(alice.storage, alice.device, BOB, reply!, { now: () => LATER });
      expect(back.kind === 'decrypted' ? back.text : null).toBe('since when?');

      const second = await sendTo(alice, BOB, 'this morning');
      expect(second?.keys[0].keyExchange).toBe(false);
      const again = await receiveOmemo(bob.storage, bob.device, ALICE, second!, { now: () => LATER });
      expect(again.kind === 'decrypted' ? again.text : null).toBe('this morning');
    });

    await it('gives every addressed device a copy of the same message', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const alicePhone = await join(net, ALICE);
      const bobLaptop = await join(net, BOB);
      const bobPhone = await join(net, BOB);

      const stanza = await sendTo(alice, BOB, 'both of you');
      expect(stanza?.keys.length).toBe(3);
      for (const reader of [bobLaptop, bobPhone, alicePhone]) {
        const sender = reader.jid === ALICE ? ALICE : ALICE;
        const opened = await receiveOmemo(reader.storage, reader.device, sender, stanza!, {
          now: () => LATER,
        });
        expect(opened.kind === 'decrypted' ? opened.text : opened.kind).toBe('both of you');
      }
    });

    await it('builds a session for a device that appeared after the last message', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const bobLaptop = await join(net, BOB);
      // Let the laptop finish its key exchange, so only the new device still needs one.
      const first = await sendTo(alice, BOB, 'first');
      await receiveOmemo(bobLaptop.storage, bobLaptop.device, ALICE, first!, { now: () => LATER });
      const reply = await sendTo(bobLaptop, ALICE, 'go on');
      await receiveOmemo(alice.storage, alice.device, BOB, reply!, { now: () => LATER });

      const bobPhone = await join(net, BOB);
      const later = new Date(LATER.getTime() + 2 * 60 * 60 * 1000);
      const plan = await planOmemoSend(alice.pep, alice.storage, alice.device, ALICE, BOB, {
        now: () => later,
      });
      const stanza = await encryptOmemo(alice.storage, alice.device, plan!, 'second', { now: () => later });
      const byDevice = new Map(stanza.keys.map((k) => [k.deviceId, k.keyExchange]));
      expect(byDevice.get(bobLaptop.device.deviceId)).toBe(false);
      expect(byDevice.get(bobPhone.device.deviceId)).toBe(true);

      const opened = await receiveOmemo(bobPhone.storage, bobPhone.device, ALICE, stanza, {
        now: () => later,
      });
      expect(opened.kind === 'decrypted' ? opened.text : opened.kind).toBe('second');

      const trust = await recipientTrust(alice.storage, plan!);
      expect(trust.length).toBe(2);
      expect(trust.every((t) => t.trust === 'blind')).toBe(true);
      expect(trust.filter((t) => t.pendingKeyExchange).length).toBe(1);
    });

    await it('sends an empty message with key material and no payload', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const bob = await join(net, BOB);

      const stanza = await sendTo(alice, BOB, null);
      expect(stanza?.payload).toBeUndefined();
      expect(stanza?.iv.length).toBe(LEGACY_PROFILE.payloadIvLength);
      const opened = await receiveOmemo(bob.storage, bob.device, ALICE, stanza!, { now: () => LATER });
      expect(opened.kind).toBe('decrypted');
      expect(opened.kind === 'decrypted' ? opened.text : 'not null').toBe(null);

      // The session it established carries the next real message without a second key exchange.
      const real = await sendTo(bob, ALICE, 'got it');
      expect(real?.keys[0].keyExchange).toBe(false);
    });

    await it('leaves no session behind when a ratchet step fails', async () => {
      const store = SecretStore.open(':memory:');
      try {
        const storage = new FlakyStorage(store);
        const device = await ensureOwnDevice(storage);
        const first = await standaloneBundle();
        const second = await standaloneBundle();
        const addresses: DeviceAddress[] = [
          { jid: BOB, deviceId: first.device.deviceId as DeviceId },
          { jid: BOB, deviceId: second.device.deviceId as DeviceId },
        ];
        const plan: OmemoSendPlan = {
          recipients: [
            { address: addresses[0], bundle: first.keys },
            { address: addresses[1], bundle: second.keys },
          ],
          skipped: [],
          staleDeviceList: false,
        };

        storage.failAfter = 1;
        let failed = false;
        try {
          await encryptOmemo(storage, device, plan, 'half a message', { now: () => START });
        } catch {
          failed = true;
        }
        expect(failed).toBe(true);
        // The first device's ratchet DID step before the second one threw. Both are gone, and so
        // is the identity the same transaction noted: one step is never half-written (§4).
        expect(await storage.loadSession(addresses[0])).toBeUndefined();
        expect(await storage.loadIdentity(addresses[0])).toBeUndefined();

        storage.failAfter = Number.POSITIVE_INFINITY;
        await encryptOmemo(storage, device, plan, 'a whole one', { now: () => START });
        expect((await storage.loadSession(addresses[0])) !== undefined).toBe(true);
        expect((await storage.loadSession(addresses[1])) !== undefined).toBe(true);
      } finally {
        store.close();
      }
    });
  });

  await describe('the stanza a send puts on the wire', async () => {
    const stanza = {
      senderDeviceId: 7 as DeviceId,
      keys: [{ deviceId: 9 as DeviceId, keyExchange: true, bytes: new Uint8Array([1, 2, 3]) }],
      iv: new Uint8Array(12).fill(4),
      payload: new Uint8Array([5, 6, 7, 8]),
    };

    await it('carries the fallback body, XEP-0380 and a plaintext message’s envelope', async () => {
      const message = encryptedChatMessage({ to: BOB, id: 'id-1', encrypted: stanza, fallback: 'encrypted' });
      expect(message.getChildText('body')).toBe('encrypted');
      expect(message.getChild('encryption', NS.eme)?.attrs.namespace).toBe(NS.omemoLegacy);
      expect(message.getChild('origin-id', NS.sid)?.attrs.id).toBe('id-1');
      expect(message.getChild('request', NS.receipts) !== undefined).toBe(true);
      expect(message.getChild('store', NS.hints) !== undefined).toBe(true);

      const parsed = parseEncryptedElement(
        message.getChild('encrypted', NS.omemoLegacy) as unknown as XmlElement,
      );
      expect(parsed?.senderDeviceId).toBe(stanza.senderDeviceId);
      expect(parsed?.keys[0].keyExchange).toBe(true);
      expect(toBase64(parsed?.payload ?? new Uint8Array())).toBe(toBase64(stanza.payload));
    });

    await it('asks for no storage and no receipt when it is a heartbeat', async () => {
      const message = omemoHeartbeat(BOB, 'id-2', { ...stanza, payload: undefined });
      expect(message.getChild('body')).toBeUndefined();
      expect(message.getChild('no-store', NS.hints) !== undefined).toBe(true);
      expect(message.getChild('no-permanent-store', NS.hints) !== undefined).toBe(true);
      expect(message.getChild('origin-id', NS.sid)).toBeUndefined();
      expect(message.getChild('request', NS.receipts)).toBeUndefined();
    });
  });
}
